constexpr long version_part(char const* text, int which) {
    for (; which > 0; which--) {
        while (*text != '.') text++;
        text++;
    }
    long value = 0;
    while (*text >= '0' && *text <= '9') value = value * 10 + (*text++ - '0');
    return value;
}

